            //
            aWandererH = aWandererH ^ ((RotL64(aPrevious, 39U) + RotL64(aOrbiterE, 11U)) + aOrbiterJ);
            aWandererA = aWandererA + (((RotL64(aCross, 19U) + RotL64(aOrbiterA, 19U)) + aOrbiterC) + aWUSaltA[((aIndex + 295U)) & S_SALT1]);
