            aWandererG = aWandererG ^ (((((RotL64(aPrevious, 14U) + RotL64(aOrbiterJ, 48U)) + aOrbiterB) + RotL64(aCarry, 53U)) + aNonceWordO) + aWUSaltB[(((511U - aIndex) + 353U)) & S_SALT1]);
