            aOrbiterC = RotL64((aOrbiterC * 0x6022B0454EC5F047ULL), 39U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterJ) + 0x5B5373EE9C1D718CULL) + aOUSaltG[(((511U - aIndex) + 40U)) & S_SALT1];
            aOrbiterK = (((aOrbiterK ^ aOrbiterI) ^ 0xFD8BEF25C0B38E95ULL) ^ aOUSaltE[(((511U - aIndex) + 313U)) & S_SALT1]) ^ aNonceWordF;
            aOrbiterK = RotL64((aOrbiterK * 0x5D18F7CA16E5FAEDULL), 13U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterA) + 0x5D0F715F569916CCULL;
