            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0xCE5BB67B7EF1A020ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0xCAF2ECED6E48C1E8ULL;
