            aWandererH = aWandererH + (((RotL64(aScatter, 21U) + aOrbiterF) + RotL64(aOrbiterI, 47U)) + aNonceWordE);
            aWandererJ = aWandererJ ^ (((RotL64(aPrevious, 39U) + RotL64(aOrbiterA, 35U)) + aOrbiterB) + aWUSaltA[(((511U - aIndex) + 86U)) & S_SALT1]);
