            aIngress = (RotL64(aVaporLaneA[((aIndex + 9593U)) & S_BLOCK1], 57U) ^ RotL64(aWindLaneC[((aIndex + 6595U)) & S_BLOCK1], 28U));
            aIngress ^= RotL64(aCrystalLaneC[((S_BLOCK1 - aIndex + 7013U)) & S_BLOCK1], 3U);
