            aCross = (RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 10044U)) & S_BLOCK1], 12U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 6204U)) & S_BLOCK1], 21U));
